const STORAGE_KEY = "notepad-content";

let hasUnsavedChanges = false;

function onBeforeUnload(e) {
    if (hasUnsavedChanges) {
        e.preventDefault();
    }
}

window.addEventListener("beforeunload", onBeforeUnload);

export function load() {
    return localStorage.getItem(STORAGE_KEY) ?? "";
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
    hasUnsavedChanges = false;
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
    hasUnsavedChanges = false;
}

export function setUnsavedChanges(value) {
    hasUnsavedChanges = value;
}

@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<script type="module" src="@Assets["Components/Pages/Notepad.razor.js"]"></script>

<h1>Notepad</h1>

<div class="mb-3">
    <textarea class="form-control" rows="12" @bind="content" @bind:event="oninput"
              @bind:after="OnContentChanged" placeholder="Type your notes here..."></textarea>
</div>

<div class="d-flex align-items-center gap-3">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-outline-danger" @onclick="Clear">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = "";
    private string savedContent = "";
    private DateTime? lastSavedAt;
    private IJSObjectReference? module;
    private Timer? autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        module = await JS.InvokeAsync<IJSObjectReference>("import",
            Assets["Components/Pages/Notepad.razor.js"]);

        content = await module.InvokeAsync<string>("load");
        savedContent = content;

        autoSaveTimer = new Timer(AutoSaveCallback, null, TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));

        StateHasChanged();
    }

    private async Task OnContentChanged()
    {
        if (module is not null && content != savedContent)
        {
            await module.InvokeVoidAsync("setUnsavedChanges", true);
        }
    }

    private async void AutoSaveCallback(object? state)
    {
        await InvokeAsync(async () =>
        {
            if (content != savedContent)
            {
                await SaveContent();
                StateHasChanged();
            }
        });
    }

    private async Task SaveNow()
    {
        await SaveContent();
    }

    private async Task SaveContent()
    {
        if (module is null) return;
        await module.InvokeVoidAsync("save", content);
        savedContent = content;
        lastSavedAt = DateTime.Now;
    }

    private async Task Clear()
    {
        if (module is null) return;
        content = "";
        savedContent = "";
        lastSavedAt = null;
        await module.InvokeVoidAsync("clear");
    }

    public async ValueTask DisposeAsync()
    {
        if (autoSaveTimer is not null)
        {
            await autoSaveTimer.DisposeAsync();
        }
        if (module is not null)
        {
            await module.InvokeVoidAsync("setUnsavedChanges", false);
            await module.DisposeAsync();
        }
    }
}

